__ht__function(json, dm, view, datas) {// ===== 获取 GraphView 和数据模型 =====
var view = graphView.getView();
var dm = graphView.dm();
//滚动条不可见
graphView.setScrollBarVisible(false);
// 获取实时纵坐标基准点
var rolly1 = dm.getDataByTag('roll-y1');
var rolly2 = dm.getDataByTag('roll-y2');
var rolly3 = dm.getDataByTag('roll-y3');

// ✅ 使用函数动态获取 Y 坐标
function getYTrack(index) {
    switch (index) {
        case 0: return rolly1.getPosition().y;
        case 1: return rolly2.getPosition().y;
        case 2: return rolly3.getPosition().y;
        default: return 0;
    }
}

// 轨道配置
var segmentLength = 1800;
var allSteelLines = {};
var lastPositions = {};
var animationFrames = {};
var steelLineShapesCollection = [];

// ===== 工具函数：创建钢条 shape =====
// 【修改】新增 cardNo 参数
function createSteelLineShapes(rollnum, cardNo) {
    const lineShapes = [];

    for (let i = 0; i < 3; i++) {
        let line = new ht.Shape();
        line.setTag(`steel-${rollnum}-track-${i}`);
        // 【修改】label 从 rollnum 改为 cardNo
        line.setStyle('label', String(cardNo));
        line.setStyle('label.position', "3");
        line.setStyle('label.font', "16px arial, sans-serif");
        line.setStyle('label.color', "rgb(255,255,255)");
        line.setStyle('shape.border.width', 6);
        line.setStyle('shape.border.color', 'red');
        line.setStyle('shape.type', 'polyline');
        line.setStyle('shadow2', true);
        line.setStyle('shadow2.color', "rgb(255,72,0)");
        line.setStyle('shadow2.blur', 10);
        line.setStyle('shadow2.offset.x', 0);
        line.setStyle('shadow2.offset.y', 0);
        line.setStyle('2d.movable', false);
        line.setStyle('shape.repeat.image', 'symbols/青岛特钢/扁钢钢坯.json'); // 设置图像并平铺
        line.setLayer('0');
        line.setPoints([]);
        dm.add(line);
        lineShapes.push(line);
    }

    return lineShapes;
}

// ===== 工具函数：更新轨道显示 =====
function updateSteelLines(rollnum, headX, tailX) {
    const lineShapes = allSteelLines[rollnum];
    if (!lineShapes) return;

    for (let i = 0; i < 3; i++) {
        const trackStart = i * segmentLength;
        const trackEnd = trackStart + segmentLength;
        const y = getYTrack(i);  // ✅ 动态获取 Y

        const visibleStart = Math.max(headX, trackStart);
        const visibleEnd = Math.min(tailX, trackEnd);

        if (visibleStart < visibleEnd) {
            const relativeStartX = visibleStart - trackStart;
            const relativeEndX = visibleEnd - trackStart;

            lineShapes[i].setPoints([
                { x: relativeStartX, y: y },
                { x: relativeEndX, y: y }
            ]);
        } else {
            lineShapes[i].setPoints([]);
        }
    }
}

// ===== 工具函数：绘制位移动画函数 =====
function animateSteelLine(rollnum, fromHeadX, fromTailX, fromLen, toHeadX, toTailX, toLen) {
    const duration = 1000;
    const startTime = performance.now();

    if (animationFrames[rollnum]) {
        cancelAnimationFrame(animationFrames[rollnum]);
    }

    function animateFrame(currentTime) {
        const elapsed = currentTime - startTime;
        const t = Math.min(elapsed / duration, 1);

        const currentHeadX = fromHeadX + (toHeadX - fromHeadX) * t;
        const currentTailX = fromTailX + (toTailX - fromTailX) * t;

        updateSteelLines(rollnum, currentHeadX, currentTailX);

        if (t < 1) {
            animationFrames[rollnum] = requestAnimationFrame(animateFrame);
        } else {
            delete animationFrames[rollnum];
        }
    }

    animationFrames[rollnum] = requestAnimationFrame(animateFrame);
}

// ===== 工具函数：动画函数 =====
function drawSteel(rollnum, cardNo, headX, tailX, len) {
    if (!rollnum) {
        if (allSteelLines[rollnum]) {
            allSteelLines[rollnum].forEach(shape => shape.s('2d.visible', false));
        }
        return;
    }

    if (!allSteelLines[rollnum]) {
        // 【修改】传入 cardNo
        allSteelLines[rollnum] = createSteelLineShapes(rollnum, cardNo);
        updateSteelLines(rollnum, headX, tailX);
        allSteelLines[rollnum].forEach(shape => shape.s('2d.visible', true));
        lastPositions[rollnum] = { headX, tailX, len };
        return;
    }

    allSteelLines[rollnum].forEach(shape => shape.s('2d.visible', true));

    let last = lastPositions[rollnum] || { headX, tailX, len };
    updateSteelLabel(rollnum, cardNo);
    // ✅ 后退时直接渲染，不执行动画
    if (tailX < last.tailX) {
        console.log(tailX,last.tailX)
        updateSteelLines(rollnum, headX, tailX);
    } else {
        animateSteelLine(rollnum, last.headX, last.tailX, last.len, headX, tailX, len);
    }

    lastPositions[rollnum] = { headX, tailX, len };
}

// ===== 新增：更新钢条标签（cardNo）=====
function updateSteelLabel(rollnum, cardNo) {
  const lineShapes = allSteelLines[rollnum];
  if (!lineShapes) return;
  
  // 三条轨道都更新成最新 cardNo
  lineShapes.forEach(line => {
    line.setStyle('label', String(cardNo || ''));
  });
}

// ✅ 更新全局 shape 集合
function updateSteelLineShapesCollection() {
    steelLineShapesCollection = [];

    Object.values(allSteelLines).forEach(shapeList => {
        steelLineShapesCollection.push(...shapeList);
    });
}

// ===== 主函数：渲染多个钢条数据 =====
// 【修改】适配新数据格式 [rollnum, cardNo, start, end]
function renderMultipleSteels(dataList) {
    const newRollnums = new Set();

    dataList.forEach(([rollnum, cardNo, start, end]) => {
        let headX = Number(end);
        let tailX = Number(start);
        let steelLength = Number(start - end);

        newRollnums.add(rollnum);
        // 【修改】传入 cardNo
        drawSteel(rollnum, cardNo, headX, tailX, steelLength);
    });

    Object.keys(allSteelLines).forEach(rollnum => {
        if (!newRollnums.has(rollnum)) {
            allSteelLines[rollnum].forEach(shape => dm.remove(shape));
            delete allSteelLines[rollnum];
            delete lastPositions[rollnum];
            if (animationFrames[rollnum]) {
                cancelAnimationFrame(animationFrames[rollnum]);
                delete animationFrames[rollnum];
            }
        }
    });

    updateSteelLineShapesCollection();
}



// ===== 时间流 =====
// SteelFactStore（事实仓库）
const SteelFactStore = {
    initialized: false,
    data: {},

    load() {
        const cache = localStorage.getItem('SteelFactStore');

        if (!cache) return;

        try {
            const obj = JSON.parse(cache);

            this.initialized = obj.initialized || false;
            this.data = obj.data || {};

            console.log('[SteelFactStore] 恢复成功');
        } catch (err) {
            console.error('[SteelFactStore] 恢复失败', err);
        }
    },

    save() {
        localStorage.setItem(
            'SteelFactStore',
            JSON.stringify({
                initialized: this.initialized,
                data: this.data
            })
        );
    }
};

// SteelStateStore（运动状态仓库）
const SteelStateStore = {
    data: {},

    load() {
        const cache = localStorage.getItem('SteelStateStore');

        if (!cache) return;

        try {
            this.data = JSON.parse(cache);

            console.log('[SteelStateStore] 恢复成功');
        } catch (err) {
            console.error('[SteelStateStore] 恢复失败', err);
        }
    },

    save() {
        localStorage.setItem(
            'SteelStateStore',
            JSON.stringify(this.data)
        );
    }
};

//速度初始化配置
const SPEED_CONFIG = {
    default: 10,

    rough: 80,

    middle: 120,

    preFinish: 180,

    finish: 250
};

//实时速度匹配
function getSteelMotionState(steel) {

    const headInMill =
        isHeadInMill(steel.headX);

    const tailInMill =
        isHeadInMill(steel.tailX);

    if (!headInMill && !tailInMill) {

        return 'ROLLER';
    }

    return 'ROLLING';
}

//缓存仓库初始化
SteelFactStore.load();
SteelStateStore.load();
startSteelSimulator();

//钢坯长度计算
function getSteelLength(steel) {

    return Math.max(
        0,
        steel.headX - steel.tailX
    );

}

//事件：轧线新增钢坯
function addSteelToState(item) {

    if (SteelStateStore.data[item.slabNo]) {
        return;
    }

    SteelStateStore.data[item.slabNo] = {

        slabNo: item.slabNo,

        cardNo: item.cardNo,

        // ===== 运动状态 =====
        state: 'ENTRY',

        // ===== 头尾位置 =====
        headX: 0,
        tailX: 0,

        // ===== 当前速度 =====
        headSpeed: 0,
        tailSpeed: 0,

        // ===== 时间 =====
        createTime: Date.now(),
        updateTime: Date.now()
    };

    console.log(
        '[钢坯进入轧线]',
        item.slabNo
    );
}

//事件：轧线下线钢坯
function removeSteelFromState(slabNo) {

    const steel = SteelStateStore.data[slabNo];

    if (!steel) {
        return;
    }

    console.log(
        '[钢坯离开轧线]',
        slabNo
    );

    delete SteelStateStore.data[slabNo];

    SteelStateStore.save();
}

//建立事实基线
function buildFactBaseline(rawData) {

    rawData.forEach(item => {

        SteelFactStore.data[item.slabNo] = {
            ...item,
            updateTime: Date.now()
        };

    });

    SteelFactStore.initialized = true;

    SteelFactStore.save();

    console.log(
        '[FactStore] 基线建立完成'
    );
}

//更新真实数据仓库
function updateFactStore(rawData) {

    rawData.forEach(item => {

        const slabNo = item.slabNo;

        if (!SteelFactStore.data[slabNo]) {

            addSteelToState(item);
        }

        SteelFactStore.data[slabNo] = {
            ...item,
            updateTime: Date.now()
        };
    });

    SteelFactStore.save();
}

//只定义了轧机区域-其他中间区域未定义
const MILL_ZONES = [
    { name: 'ROUGH', start: 320,  end: 630  },
    { name: 'MIDDLE', start: 1100, end: 1500 },
    { name: 'PF',     start: 1600, end: 1800 },
    { name: 'FINISH', start: 3380, end: 3550 }
];

//钢坯状态判定
function updateSteelPhase(steel) {

    const length =
        getSteelLength(steel);

    // ===== 出钢阶段 =====
    if (length < 150) {

        steel.state = 'ENTRY';

        return;
    }

    // ===== 轧制阶段 =====
    if (isHeadInMill(steel)) {

        steel.state = 'ROLLING';

        return;
    }

    // ===== 辊道运输 =====
    steel.state = 'ROLLER';
}

//是否在轧制中-其他状态未定义
function isHeadInMill(steel) {

    return MILL_ZONES.some(zone => {

        return (
            steel.headX >= zone.start &&
            steel.headX <= zone.end
        );

    });

}

//状态判断函数
function getSteelMotionState(steel) {

    const headInMill =
        isHeadInMill(steel.headX);

    const tailInMill =
        isHeadInMill(steel.tailX);

    if (!headInMill && !tailInMill) {

        return 'ROLLER';
    }

    return 'ROLLING';
}

//速度策略函数
function updateSteelSpeed(steel) {

    switch (steel.state) {

        // ===== 出钢 =====
        case 'ENTRY':

            steel.headSpeed = 20;

            // 尾部不动
            steel.tailSpeed = 0;

            break;

        // ===== 轧制 =====
        case 'ROLLING':

            steel.headSpeed = 20;

            steel.tailSpeed = 5;

            break;

        // ===== 辊道 =====
        case 'ROLLER':

            steel.headSpeed = 35;

            steel.tailSpeed = 35;

            break;
    }
}

//位置求解函数
function updateSteelPosition(
    steel,
    dt
) {

    steel.headX +=
        steel.headSpeed * dt;

    steel.tailX +=
        steel.tailSpeed * dt;

    if (steel.tailX < 0) {

        steel.tailX = 0;
    }
}

//运算推演核心
function updateSteelStates() {

    const now = Date.now();

    const removeList = [];

    Object.values(
        SteelStateStore.data
    ).forEach(steel => {

        const dt =
            (now - steel.updateTime) / 1000;

        steel.updateTime = now;

        // 1 状态判定
        updateSteelPhase(steel);

        // 2 速度策略
        updateSteelSpeed(steel);

        // 3 位置求解
        updateSteelPosition(
            steel,
            dt
        );

        // 4 离线判断
        if (steel.tailX >= 5400) {

            removeList.push(
                steel.slabNo
            );
        }
    });

    removeList.forEach(
        removeSteelFromState
    );
}

//接入flow
function buildRenderData() {

    return Object.values(
        SteelStateStore.data
    ).map(steel => [

        steel.slabNo,

        steel.cardNo,

        steel.headX,

        steel.tailX

    ]);
}

//启动运行模型
function startSteelSimulator() {

    setInterval(() => {

        updateSteelStates();

        renderMultipleSteels(
            buildRenderData()
        );

        SteelStateStore.save();

    }, 100);
}



// ===== 监听数据变化 =====
dataModel.addDataPropertyChangeListener(function (e) {

    if (e.property === 'a:rolltable') {
    // 1. 安全获取原始数据
    const rawData = e.newValue?.data || [];

    if (!SteelFactStore.initialized) {

        buildFactBaseline(rawData);

    } else {

        updateFactStore(rawData);

    }
    }
});

// 1. 先获取轨道坐标映射表（名称 → 整数坐标）
function getTrackPositionMap() {
  const map = {};
  dm.each(item => {
    const tag = item.getTag();
    if (tag && tag.startsWith('track-')) {
      const match = tag.match(/track-(\d+)-(.+)/);
      if (!match) return;
      
      const trackNum = parseInt(match[1], 10);
      const name = match[2];
      const baseX = item.getX();
      const offset = (trackNum - 1) * 1800;
      const finalX = baseX + offset;
      
      // 忽略小数点，取整数
      map[name] = Math.floor(finalX);
    }
  });
  return map;
}

// 2. 数据转换：对象数组 → 你的 [slabNo, cardNo, headX, tailX] 坐标数组
function transformSteelData(data) {
  if (!Array.isArray(data)) return [];
  
  // 先获取坐标映射
  const trackMap = getTrackPositionMap();
  
  return data.map(item => {
    // 从映射表中取出坐标，没有则给 0
    const headX = trackMap[item.headPosition] || 0;
    const tailX = trackMap[item.tailPosition] || 0;
    
    // 最终输出：[slabNo, cardNo, head坐标, tail坐标]
    return [
      item.slabNo || '',
      item.cardNo || '',
      headX,
      tailX
    ];
  });
}

// ===== 右键菜单逻辑 =====
const menuItems = [
    { label: "钢坯轧废", fordata: 1, action: () => handleMenuClick("钢坯轧废") },
    { label: "钢坯剔料", fordata: 1, action: () => handleMenuClick("钢坯剔料") },
    { label: "跟踪清除", fordata: 1, action: () => handleMenuClick("跟踪清除") },
    { label: "查看计划", fordata: 1, action: () => handleMenuClick("查看计划") },
    { label: "查看实绩", fordata: 1, action: () => handleMenuClick("查看实绩") }
];

const contextmenu = new ht.widget.ContextMenu(menuItems);
contextmenu.setVisibleFunc(item => steelLineShapesCollection.includes(graphView.sm().ld()));
contextmenu.addTo(view);

function handleMenuClick(menuLabel) {
    const data = graphView.sm().ld();
    if (!data || !steelLineShapesCollection.includes(data)) {
        alert("未选中合适的节点，点击的菜单项：" + menuLabel);
        return;
    }

    const line = data.getAttr("Line") || "B101";
    // 轧线钢坯参数
    let slabNo = data.s('label');

    switch (menuLabel) {
        case "钢坯轧废": handleRollChange("1"); break;
        case "钢坯剔料": handleRollChange("2"); break;
        case "跟踪清除": requestfallowDelete(line,slabNo); break;
        case "查看计划": requestPlanView(); break;
        case "查看实绩": requestTrueView(); break;
        default: console.warn("未处理的菜单项:", menuLabel);
    }
}

